/**
 * Replays the backend's fairness vectors through this app's verifier.
 *
 * Two independent implementations of a provably-fair algorithm drift silently
 * unless something forces them together. This is that something: the fixture is
 * generated by `go test ./gacha/fair -update` in tlc-service, and every value in
 * it must come back identical from the browser code that customers rely on. If
 * they disagree, a player checking their own receipt would see a mismatch and
 * reasonably conclude they were cheated.
 *
 *   npm run verify:fairness
 *
 * Node strips the TypeScript types natively (24+), so this runs the real
 * production module rather than a copy of it.
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

import { derive, TOTAL_BPS, pickRarity, sha256Hex, hexToBytes, effectiveOdds } from '../src/lib/fair-verify.ts';

const here = dirname(fileURLToPath(import.meta.url));
const fixturePath = resolve(here, '../src/lib/__fixtures__/fairness-vectors.json');
const vectors = JSON.parse(readFileSync(fixturePath, 'utf8'));

let failures = 0;

function check(name, actual, expected) {
  const ok = JSON.stringify(actual) === JSON.stringify(expected);
  if (!ok) {
    failures += 1;
    console.error(`  ✗ ${name}\n      expected ${JSON.stringify(expected)}\n      actual   ${JSON.stringify(actual)}`);
  }
  return ok;
}

for (const vector of vectors) {
  console.log(`\n${vector.name}`);

  const preimage = hexToBytes(vector.preimage);
  const randomness = hexToBytes(vector.randomness);

  check('commit hash', await sha256Hex(preimage), vector.commit_hash);

  const stock = Object.fromEntries(vector.pool.map((p) => [p.rarity_code, p.card_ids.length]));
  check('effective odds', effectiveOdds(vector.published_odds, stock), vector.effective_odds);

  const roll = (await derive(randomness, preimage, 0)) % TOTAL_BPS;
  check('rarity roll', roll, vector.rarity_roll);
  check('rarity', pickRarity(vector.effective_odds, roll), vector.rarity_code);

  const candidates = [...(vector.pool.find((p) => p.rarity_code === vector.rarity_code)?.card_ids ?? [])].sort();
  const index = (await derive(randomness, preimage, 1)) % candidates.length;
  check('card index', index, vector.card_index);
  check('card id', candidates[index], vector.card_id);

  if (failures === 0) console.log('  ✓ all values reproduce');
}

if (failures > 0) {
  console.error(`\n${failures} mismatch(es). The browser verifier and the backend disagree — do not ship.`);
  process.exit(1);
}
console.log(`\n✓ ${vectors.length} vectors reproduce exactly.`);
